-- Run in a transaction and ROLLBACK. Isolated identities, product, Page and reports only.
create temporary table operations_qa_results(label text primary key,passed boolean);
create function pg_temp.check_operations(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'QA FAILED: %',label;end if;insert into operations_qa_results values(label,true);end $$;
create function pg_temp.reject_writeoff_audit() returns trigger language plpgsql as $$ begin if new.action='inventory_writeoff' then raise exception 'QA audit failure';end if;return new;end $$;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();m uuid:=gen_random_uuid();p uuid:=gen_random_uuid();item uuid;o uuid;one uuid;two uuid;unowned uuid;r1 uuid;r2 uuid;pay uuid;result jsonb;failed boolean;d date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date-1;body jsonb;before_orders bigint;
begin
 insert into auth.users(id,email) values(a,'qa-admin-'||a||'@example.invalid'),(u,'qa-one-'||u||'@example.invalid'),(v,'qa-two-'||v||'@example.invalid'),(m,'qa-manager-'||m||'@example.invalid');
 insert into public.profiles(id,email,role,status,permissions) values(a,'qa@example.invalid','super_admin','active','{}'),(u,'qa@example.invalid','viewer','active','{}'),(v,'qa@example.invalid','viewer','active','{}'),(m,'qa@example.invalid','manager','active','{"sales_operations":["verify_reports"]}');
 insert into public.user_reporting_lines(employee_user_id,manager_user_id,status,created_by) values(u,m,'active',a),(v,m,'active',a);
 insert into public.sales_products(id,sku,name,unit_price_vnd,status,product_group) values(p,'QA-'||p,'QA operations',100000,'active','fanpage');
 result:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','970000000001','page_name','QA operations','page_link','https://facebook.com/970000000001','purchase_cost_vnd',45000));item:=(result->'item'->>'id')::uuid;
 perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',item));result:=public.sales_inventory_command('create_inhouse_order',a,jsonb_build_object('product_id',p,'buyer_user_id',u,'quantity',1));o:=(result->>'order_id')::uuid;
 perform public.sales_inventory_command('reserve',a,jsonb_build_object('order_id',o,'destination','inhouse','inventory_item_ids',jsonb_build_array(item)));perform public.sales_inventory_command('verify_zero',a,jsonb_build_object('order_id',o));perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',o));
 result:=public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',item,'user_id',u));one:=(result->>'assignment_id')::uuid;result:=public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',item,'user_id',v));two:=(result->>'assignment_id')::uuid;
 update public.page_assignments set assigned_at=now()-interval '2 days' where id in(one,two);
 result:=public.inhouse_payout_save(a,jsonb_build_object('page_id','970000000001','external_id','QA-'||p,'profile_name','QA payout','currency','USD'));pay:=(result->>'payment_profile_id')::uuid;
 body:=jsonb_build_object('assignment_id',one,'report_date',d,'published_post_count',3,'revenue_vnd',100,'cumulative_revenue_vnd',300,'note','QA');
 insert into public.page_assignments(page_id,user_id) values('970000000001',null) returning id into unowned;
 failed:=false;begin perform public.content_report_command('submit',u,body||jsonb_build_object('assignment_id',unowned));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'null assignee cannot be claimed for reporting');
 failed:=false;begin perform public.content_report_command('submit',v,body);exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'cannot submit another person assignment');
 result:=public.content_report_command('submit',u,body);r1:=(result->'report'->>'id')::uuid;perform public.content_report_command('submit',u,body||'{"published_post_count":5}');
 perform pg_temp.check_operations((select count(*)=1 from public.content_assignment_daily_reports where assignment_id=one) and (select count(*)=2 from public.content_report_revisions where report_id=r1),'one assignment day with preserved revisions');
 result:=public.content_report_command('submit',v,body||jsonb_build_object('assignment_id',two,'published_post_count',4,'revenue_vnd',200,'cumulative_revenue_vnd',500));r2:=(result->'report'->>'id')::uuid;
 perform pg_temp.check_operations((select sum(published_post_count)=9 and sum(revenue_vnd)=300 from public.content_assignment_daily_reports where page_id='970000000001'),'two people independent results sum to page');
 failed:=false;begin perform public.content_report_command('verify',u,jsonb_build_object('report_id',r1));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'viewer cannot verify');
 update public.profiles set permissions='{"sales_operations":["verify_reports"]}' where id=u;
 failed:=false;begin perform public.content_report_command('verify',u,jsonb_build_object('report_id',r1));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'cannot verify own report even with scope');
 perform public.content_report_command('verify',m,jsonb_build_object('report_id',r1));result:=public.content_report_command('verify',m,jsonb_build_object('report_id',r1));perform pg_temp.check_operations((result->>'duplicate')::boolean,'manager with scope verifies branch idempotently');
 failed:=false;begin perform public.content_report_command('submit',u,body);exception when raise_exception then if sqlerrm='Verified report is locked' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'verified report cannot be overwritten');
 perform public.content_report_command('reject',m,jsonb_build_object('report_id',r2,'note','QA add evidence'));perform public.content_report_command('submit',v,body||jsonb_build_object('assignment_id',two));perform pg_temp.check_operations((select status='submitted' from public.content_assignment_daily_reports where id=r2),'rejected report can be revised and resubmitted');
 failed:=false;begin perform public.inhouse_payout_save(u,jsonb_build_object('page_id','970000000001','external_id','QA payout'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'payout requires explicit permission');
 result:=public.inhouse_payout_save(a,jsonb_build_object('page_id','970000000001','payment_profile_id',pay));
 perform public.inhouse_payout_save(a,jsonb_build_object('page_id','970000000001','payment_profile_id',pay));perform pg_temp.check_operations((select source='manual_inhouse' and last_synced_at is null from public.payment_profiles where id=pay) and (select count(*)=1 from public.page_payment_profiles where page_id='970000000001'),'manual payout attached once without Meta sync');
 failed:=false;begin perform public.sales_inventory_writeoff(u,jsonb_build_object('inventory_item_id',item,'reason','QA'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'writeoff denied without explicit scope');
 create trigger qa_writeoff_audit before insert on public.admin_audit_logs for each row execute function pg_temp.reject_writeoff_audit();
 failed:=false;begin perform public.sales_inventory_writeoff(a,jsonb_build_object('inventory_item_id',item,'reason','QA'));exception when raise_exception then if sqlerrm='QA audit failure' then failed:=true;else raise;end if;end;
 perform pg_temp.check_operations(failed and (select status='inhouse_transferred' from public.sales_inventory_items where id=item) and not exists(select 1 from public.sales_inventory_writeoffs where inventory_item_id=item),'writeoff audit failure rolls back status loss ledger');drop trigger qa_writeoff_audit on public.admin_audit_logs;
 select count(*) into before_orders from public.sales_orders;perform public.sales_inventory_writeoff(a,jsonb_build_object('inventory_item_id',item,'reason','QA damaged'));result:=public.sales_inventory_writeoff(a,jsonb_build_object('inventory_item_id',item,'reason','QA duplicate'));
 perform pg_temp.check_operations((result->>'duplicate')::boolean and (select count(*)=1 and sum(cost_vnd)=45000 and sum(revenue_vnd)=0 from public.sales_inventory_writeoffs where inventory_item_id=item) and (select count(*)=before_orders from public.sales_orders),'writeoff cost once no revenue or new order');
 failed:=false;begin perform public.content_report_command('submit',v,body||jsonb_build_object('assignment_id',two));exception when raise_exception then if sqlerrm='Page is not active Inhouse' then failed:=true;else raise;end if;end;perform pg_temp.check_operations(failed,'damaged page stops new reports');
 failed:=false;begin perform public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',item,'user_id',v));exception when raise_exception then failed:=true;end;perform pg_temp.check_operations(failed,'damaged page cannot be reassigned');
 perform pg_temp.check_operations(not has_function_privilege('authenticated','public.content_report_command(text,uuid,jsonb)','EXECUTE') and not has_table_privilege('anon','public.content_report_revisions','SELECT'),'no client direct report access');
end $$;
select * from operations_qa_results order by label;
